<?php
// Read-only exports reuse the exact Inflow history filters, without pagination.
function ih_export_url($format){return 'index.php?'.http_build_query(array_merge(['page'=>'inflow','inflow_export'=>$format],array_intersect_key($_GET,array_flip(['inflow_q','date_from','date_to','inflow_kind','inflow_status','inflow_owner']))));}
function ih_export_toolbar(){echo '<div class="modal-actions inflow-export-actions" style="margin:12px 0;flex-wrap:wrap"><a class="btn secondary" href="'.e(ih_export_url('xlsx')).'">Download Excel</a><a class="btn ghost" href="'.e(ih_export_url('pdf')).'">Download PDF</a><a class="btn ghost" target="_blank" rel="noopener" href="'.e(ih_export_url('print')).'">Print</a></div>';}
function ih_export_build(){
 if(!access_page_allowed('inflow'))throw new Exception('Inflow access required.');
 foreach(['inflow_q','date_from','date_to','inflow_kind','inflow_status','inflow_owner'] as $key)if(isset($_GET[$key])&&!is_string($_GET[$key]))throw new Exception('Invalid Inflow filter.');
 $filter=inflow_history_query();$q=db()->prepare('SELECT b.*,u.name processed_by'.$filter['sql'].' ORDER BY b.id DESC');$q->execute($filter['args']);$rows=[];$total=0;
 foreach($q as $r){$m=json_decode($r['result_json']??'',true)?:[];$label=ih_export_status($r,$m);$qty=(int)$r['total_qty'];$total+=$qty;
  $rows[]=[$r['txn_date'],(string)($r['reference_no']?:$r['batch_ref']),(string)$r['batch_ref'],$m['reference_kind']??$r['batch_type'],$m['condition']??($r['status']==='Confirmed'?'Good Item':'Pending review'),$m['destination']??($r['status']==='Confirmed'?'Legacy / see details':'Pending review'),$qty,(string)$r['source_name'],(string)($r['processed_by']??''),$label];
 }
 $filters=[];foreach(['inflow_q'=>'Search','date_from'=>'From','date_to'=>'To','inflow_kind'=>'Type','inflow_status'=>'Status','inflow_owner'=>'Uploader'] as $key=>$label)if(trim((string)($_GET[$key]??''))!=='')$filters[]=$label.': '.($key==='inflow_owner'&&$_GET[$key]==='mine'?'My uploads':(string)$_GET[$key]);
 return ['title'=>'Inflow Transaction History','headers'=>['Date','Order ID / Reference','Batch Reference','Type','Condition','Destination','Recorded Qty (pcs)','Supplier / Source','Processed By','Status'],'rows'=>$rows,'total'=>$total,'meta'=>['Filters'=>$filters?implode('; ',$filters):'All inflow transactions','Generated'=>date('Y-m-d H:i:s').' UTC'.date('P'),'Generated By'=>current_user()['name'],'Matching Batches'=>count($rows),'Quantity Basis'=>'Recorded batch quantities, as shown in Inflow history. Draft quantities may be 0. Historical totals include reversed records and are not net inventory movement.','Scope'=>'All matching records, across every page. Latest batch first.']];
}
function ih_export_status($r,$m){
 if(($r['batch_type']??'')==='Order Return'&&in_array($r['status'],['Review','To Review','Pending Review'],true)){
  $items=$m['rows']??[];if(!empty($items[0]['unified_return']))return (int)($r['error_count']??0)>0?'Awaiting Verification':'Ready for Confirmation';
  if($items&&!array_filter($items,fn($x)=>($x['condition']??'')!=='Damaged / Leak'))return (int)($r['error_count']??0)>0?'Needs Correction':'Awaiting Uploader Validation';
 }
 return ['Confirmed'=>'Posted / Confirmed','To Review'=>'Not Submitted','Review'=>'Not Submitted','Pending Review'=>'Not Submitted','Unsuccessful'=>'Needs Correction'][$r['status']]??$r['status'];
}
function ih_export_rows($r){return array_merge($r['rows'],[['','TOTAL','','','','',$r['total'],'','','']]);}
function ih_export_html($r,$print=false){
 $html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'.e($r['title']).'</title><style>@page{size:A4 landscape;margin:12mm 9mm 16mm}body{font-family:"DejaVu Sans",Arial,sans-serif;font-size:9px;color:#16263c}h1{font-size:20px;margin:0 0 5px}p{margin:5px 0}.meta{margin:12px 0;line-height:1.5}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th,td{padding:7px 5px;border-bottom:1px solid #d9e2ed;text-align:left;vertical-align:top;word-wrap:break-word}th{background:#edf2f7}tr{page-break-inside:avoid}.qty{text-align:right;white-space:nowrap}th.qty{white-space:normal}.total{font-weight:bold}.actions{margin:0 0 14px}.actions button{padding:9px 16px}small{font-size:8px}@media print{.actions{display:none}}</style></head><body>';
 if($print)$html.='<div class="actions"><button type="button" onclick="window.print()">Print</button></div>';
 $html.='<h1>'.e($r['title']).'</h1><p>E-commerce Inventory Management System</p><div class="meta">';foreach($r['meta'] as $label=>$value)$html.='<div><b>'.e($label).':</b> '.e($value).'</div>';$html.='</div><table><colgroup>';foreach([7,13,14,9,8,10,7,10,12,10] as $width)$html.='<col style="width:'.$width.'%">';$html.='</colgroup><thead><tr>';foreach($r['headers'] as $i=>$h)$html.='<th'.($i===6?' class="qty"':'').'>'.e($h).'</th>';$html.='</tr></thead><tbody>';
 foreach(ih_export_rows($r) as $index=>$row){$html.='<tr'.($index===count($r['rows'])?' class="total"':'').'>';foreach($row as $i=>$value)$html.='<td'.($i===6?' class="qty"':'').'>'.e($i===6?number_format($value):$value).'</td>';$html.='</tr>';}
 if(!$r['rows'])$html.='<tr><td colspan="10">No matching inflow transactions.</td></tr>';
 return $html.'</tbody></table>'.($print?'<script>window.addEventListener("load",()=>window.print());</script>':'').'</body></html>';
}
function ih_write_pdf($path,$r){
 $loader=__DIR__.'/third_party/report_pdf/vendor/autoload.php';if(!is_file($loader))throw new Exception('PDF export files are missing. Upload the complete third_party/report_pdf folder.');require_once $loader;
 $options=new \Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('isJavascriptEnabled',false);$options->set('defaultFont','DejaVu Sans');$options->set('tempDir',sys_get_temp_dir());$options->set('fontCache',sys_get_temp_dir());$options->setChroot(__DIR__.'/third_party/report_pdf/vendor/dompdf/dompdf');
 $pdf=new \Dompdf\Dompdf($options);$pdf->setPaper('A4','landscape');$pdf->loadHtml(ih_export_html($r),'UTF-8');$pdf->render();$canvas=$pdf->getCanvas();$font=$pdf->getFontMetrics()->getFont('DejaVu Sans','normal');$canvas->page_text(720,570,'Page {PAGE_NUM} of {PAGE_COUNT}',$font,8,[.25,.3,.4]);if(file_put_contents($path,$pdf->output())===false)throw new Exception('Cannot save PDF export.');
}
function ih_download($format){
 $path=null;try{
  if(!in_array($format,['xlsx','pdf','print'],true))throw new Exception('Choose Download Excel, Download PDF or Print.');
  $r=ih_export_build();header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
  if($format==='print'){header('Content-Type: text/html; charset=utf-8');echo ih_export_html($r,true);return;}
  $path=tempnam(sys_get_temp_dir(),'inflow-history-');if($path===false)throw new Exception('Cannot prepare export.');
  if($format==='xlsx')report_write_xlsx($path,$r['title'],$r['headers'],ih_export_rows($r),$r['meta']);else ih_write_pdf($path,$r);
  header('Content-Type: '.($format==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'application/pdf'));header('Content-Disposition: attachment; filename="Inflow_History_'.date('Ymd_His').'.'.$format.'"');readfile($path);
 }catch(Throwable $e){http_response_code(400);header('Content-Type: text/html; charset=utf-8');echo '<h1>Inflow export unavailable</h1><p>'.e(safe_error_message($e)).'</p><a href="index.php?page=inflow">Back to Inflow</a>';}
 finally{if($path&&is_file($path))unlink($path);}
}
